/// Temporarily stores the unvisited tail beyond the vector's length.
pub(crate) struct ExtractIfCore<'a, K, V> {
    map: &'a mut IndexMapCore<K, V>,
    next: usize,
    end: usize,
    original_len: usize,
}

impl<'a, K, V> ExtractIfCore<'a, K, V> {
    pub(crate) fn new<R: RangeBounds<usize>>(map: &'a mut IndexMapCore<K, V>, range: R) -> Self {
        let original_len = map.entries.len();
        let range = simplify_range(range, original_len);
        map.erase_indices(range.start, original_len);
        // SAFETY: The iterator owns the tail until Drop restores all unvisited entries.
        // Forgetting the iterator leaks that tail, leaving a valid indexed prefix.
        unsafe { map.entries.set_len(range.start) };
        Self { map, next: range.start, end: range.end, original_len }
    }

    pub(crate) fn remaining(&self) -> usize {
        self.end - self.next
    }

    pub(crate) fn next<F>(&mut self, mut pred: F) -> Option<(K, V)>
    where F: FnMut(&K, &mut V) -> bool,
    {
        while self.next < self.end {
            // SAFETY: next points to an initialized entry owned by this iterator.
            let entry = unsafe { &mut *self.map.entries.as_mut_ptr().add(self.next) };
            let remove = pred(&entry.key, &mut entry.value);
            let index = self.next;
            self.next += 1;
            if remove {
                // SAFETY: This entry is removed from the owned tail exactly once.
                return Some(unsafe { self.map.entries.as_ptr().add(index).read() }.key_value());
            }
            let len = self.map.entries.len();
            // SAFETY: Move the retained entry into the next free prefix slot.
            // Source and destination may coincide; the old slot is never dropped.
            unsafe {
                let ptr = self.map.entries.as_mut_ptr();
                core::ptr::copy(ptr.add(index), ptr.add(len), 1);
                self.map.entries.set_len(len + 1);
            }
        }
        None
    }
}

impl<K, V> Drop for ExtractIfCore<'_, K, V> {
    fn drop(&mut self) {
        let len = self.map.entries.len();
